window.DAILY = {"generated_utc": "2026-11-17T21:49:31Z", "date_cn": "2026-11-18", "window_days": 3, "source": "arXiv OAI-PMH/API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2611.20568", "title": "sqrtVINS-Based 360 Visual-Inertial SLAM Systems: Hilti-Trimble SLAM Challenge 2026 Entry", "authors": ["Jungwoo Lee", "Hogyun Kim", "Jiwon Choi", "Jinyong Jeong", "Younggun Cho"], "abstract": "This report describes our submission to the 2026 Hilti-Trimble SLAM Challenge. The system is a 360-camera visual-inertial pipeline that uses only the provided dual-fisheye image streams and IMU measurements. First, raw images are preprocessed with low-light enhancement and static/dynamic masking, and then fed into a $\\sqrt{\\text{VINS}}$ frontend as the local odometry, with deep learning-based SuperPoint features, ELSED line segments, and LightGlue matching. The resulting trajectory is refined using a GTSAM-based backend that performs tightly-coupled factor graph optimization with SALAD global descriptor and visual bundle adjustment (BA). The backend performs local-to-global structureless BA, tightly regularized intrinsic and extrinsic refinement, and global scale adjustment supported by the known inter-camera baseline and cross-view constraints. The design targets long indoor sequences with dark regions, repetitive corridors, dynamic objects, and limited geometric parallax, while keeping the pipeline reproducible in the provided ROS2 workspace. Fig. 1 demonstrates that our proposed method aligns well with the floorplan across several indoor sequences.", "published": "2026-11-16", "comment": "2026 Hilti x Trimble SLAM Challenge at ICRA 2026 (2nd Place in the SLAM Category)", "url": "https://arxiv.org/abs/2611.20568"}, {"id": "2611.21607", "title": "ScaleVLA: Scaling Vision-Language-Action Models to 552 Billion Parameters", "authors": ["Ruixi Yu", "Dairu Liu", "Xuchuan Chen", "Zekun Qi", "Zekai Li", "Zhuo Cao", "Luyang Niu", "Yingsheng Zhang", "Sikai Liang", "Ke Fan", "He Wang", "Li Yi"], "abstract": "Frontier Vision-Language Models (VLMs) such as GPT-6 Astra have demonstrated remarkable capabilities in robot control, suggesting that broad pretraining provides knowledge valuable for physical action. Yet most Vision-Language-Action (VLA) policies still rely on much smaller VLM backbones, leaving this potential largely untapped. We ask whether frontier-scale representations can provide a stronger foundation for robot learning. We introduce ScaleVLA, which connects a 552B DeepSeek-V4.1-Flash backbone to a trainable action DiT, and systematically compare VLMs from 2B to 552B under a shared training setup. We evaluate three fundamental capabilities of robot foundation models. In sample efficiency, just 10 demonstrations outperform a 2B backbone trained with 50 (87.8% vs. 85.6%). In generalization, LIBERO-PRO success reaches 45.1%, compared with at most 31.3% for smaller backbones. In precise manipulation, real-world charger insertion improves from 4/10 to 9/10 successes, with gains concentrated in contact-sensitive alignment. Despite its scale, ScaleVLA achieves 216 ms median latency per action chunk. Our findings suggest that frontier VLMs can serve not only as reasoning agents, but also as powerful representational foundations for efficient and generalizable robot policies.", "published": "2026-11-16", "comment": "Tech Report", "url": "https://arxiv.org/abs/2611.21607"}, {"id": "2611.20098", "title": "A Geometric Observer for Visual-Inertial Odometry using Optical-Flow Constraints", "authors": ["Tarek Bouazza", "Soulaimane Berkane", "Tarek Hamel"], "abstract": "This paper presents a geometric observer for monocular visual-inertial odometry driven by individual optical-flow constraints. For each tracked point, the bearing and its rotationally compensated derivative give a depth-free homogeneous constraint on the body-frame velocity. These constraints enter the innovation of an observer on the gravity-augmented group $\\mathbb{SE}_3(3)$ through a Riccati gain, without estimating depths or reconstructing the direction of motion. The auxiliary gravity state makes the six-dimensional body-frame velocity-gravity error dynamics independent of the attitude correction, and their uniform observability is shown to be equivalent to persistent excitation of a matrix formed from the inertial bearings and their derivatives. Under this condition, the body-frame velocity and gravity errors converge globally and uniformly exponentially, and a gravity-based attitude correction renders the combined velocity, gravity, and reduced-attitude error almost globally asymptotically stable and locally uniformly exponentially stable. Simulations illustrate the excitation condition, recovery from initial errors, and sensitivity to perturbed measurements.", "published": "2026-11-15", "comment": "12 pages, 6 figures. Submitted to ECC 2027", "url": "https://arxiv.org/abs/2611.20098"}, {"id": "2611.19387", "title": "Long-Horizon Causal Inertial Odometry in Multistory Buildings", "authors": ["Tianzi Zhang", "Yan Wang", "Hao Qiao", "Jian Kuang", "Xiaoji Niu"], "abstract": "In indoor 3D localization inside multistory buildings, an elevator or an escalator accelerates for a few seconds and then cruises at constant velocity for tens of seconds. Gait excitation disappears, the specific force degenerates into a constant gravity reaction, and instantaneous velocity becomes unobservable within a 1-2 s window. The output of short-window learned inertial odometry consequently degrades toward the conditional mean of the training set, and vertical displacement is systematically underestimated. We propose Local-Token Causal Attention (LTCA), a long-horizon architecture that compresses each 1 s inertial window into a 1 Hz motion token and sustains, over a bounded 60 s causal cache, the motion state established at the onset event. We further introduce a pluggable barometer branch that, when online, supplies a direct elevation constraint to the vertical channel through local differential height observations, and we train it with paired online/fallback conditional training so that the barometer also regularizes the representation shared by the two modes during training. On MSIO, our benchmark of nine buildings, the RoNIN and TLIO instances reach 3D trajectory errors (ATE-3D) of 2.83/4.18 m and 2.44/5.12 m on the Seen and Unseen splits, respectively, with the barometer online. With the barometer disabled at inference, the same weights fall back to pure inertial inference and reach 3.24/4.28 m and 2.64/5.23 m, still below every native short-window baseline. We further validate the framework on the public RoNIN and TLIO benchmarks.", "published": "2026-11-14", "comment": null, "url": "https://arxiv.org/abs/2611.19387"}, {"id": "2611.20710", "title": "SG-ODOM: Event-Driven Proprioceptive State Estimation with Stability-Gated Contact Updates for Legged Robots", "authors": ["Francesco Iotti", "Chiyun Noh", "Franco Angelini", "Manolo Garabini", "Ayoung Kim", "Maurice Fallon", "Frank Dellaert"], "abstract": "Reliable proprioceptive state estimation for legged robots fuses inertial sensing with kinematic sensing from leg encoders. The latter assumes a foot is stationary during the stance phase; however, physical foot touchdown does not necessarily provide a stationary reference for odometry, particularly during impact and load transfer. Repeatedly applying kinematic corrections throughout the same contact phase can introduce redundant or unreliable information. We present SG-ODOM, a proprioceptive odometry framework that uses stability-gated contact selection to schedule kinematic updates. Following physical touchdown, a stability gate accepts the contact for state estimation only after the foot reaches a sufficiently stable support condition. The resulting validated touchdown event triggers an estimator correction, while additional timeout updates bound the maximum duration of uninterrupted IMU propagation. The framework is evaluated on multiple legged platforms, both quadrupedal and humanoid robots, against representative state-of-the-art proprioceptive estimators. Across the evaluated sequences, SG-ODOM demonstrates competitive or superior estimation accuracy, reducing Relative Pose Error (RPE) by up to 25% compared to the baseline estimator on outdoor sequences from the GrandTour dataset. Source code: https://github.com/ori-drs/SG-ODOM. Video: https://youtu.be/-583_RyuhqQ", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2611.20710"}, {"id": "2602.00092", "title": "Interpreting and Controlling Model Behavior via Constitutions for Atomic Concept Edits", "authors": ["Neha Kalibhat", "Zi Wang", "Prasoon Bajpai", "Drew Proud", "Wenjun Zeng", "Been Kim", "Mani Malek"], "abstract": "We introduce a black-box interpretability framework that learns a verifiable constitution: a natural language summary of how changes to a prompt affect a model's specific behavior, such as its alignment, correctness, or adherence to constraints. Our method leverages atomic concept edits (ACEs), which are targeted operations that add, remove, or replace an interpretable concept in the input prompt. By systematically applying ACEs and observing the resulting effects on model behavior across various tasks, our framework learns a causal mapping from edits to predictable outcomes. This learned constitution provides deep, generalizable insights into the model. Empirically, we validate our approach across diverse tasks, including mathematical reasoning and text-to-image alignment, for controlling and understanding model behavior. We found that for text-to-image generation, GPT-Image tends to focus on grammatical adherence, while Imagen 4 prioritizes atmospheric coherence. In mathematical reasoning, distractor variables confuse GPT-5 but leave Gemini 2.5 models and o4-mini largely unaffected. Moreover, our results show that the learned constitutions are highly effective for controlling model behavior, achieving an average of 1.86 times boost in success rate over methods that do not use constitutions. Our open-sourced code can be found at https://github.com/google-deepmind/atomic_concept_edits", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2602.00092"}, {"id": "2605.22550", "title": "MOTOR: A Multimodal Dataset for Two-Wheeler Rider Behavior Understanding", "authors": ["Varun A. Paturkar", "Shankar Gangisetty", "C. V. Jawahar"], "abstract": "Two-wheelers account for a disproportionately high share of road fatalities in the Global South. Research on two-wheeler rider behavior, however, lags far behind four-wheelers, where multimodal datasets have driven major advances in Advanced Driver Assistance Systems (ADAS). To address this gap, we present the MOtorized TwO-wheeler Rider (MOTOR) dataset, the first large-scale, multi-view, multimodal resource dedicated to two-wheelers in dense, unstructured traffic. MOTOR comprises 1,629 sequences (25+ hours of video data) collected from 16 riders and integrates synchronized front, rear, and helmet videos, rider eye-gaze from wearable trackers, on-road audio, and telemetry (GPS, accelerometer, gyroscope). Rich annotations capture traffic context, rider state, 12 riding maneuvers spanning conventional and unconventional behaviors, and legality labels (Legal, Illegal, Unspecified). We benchmark rider behavior recognition and maneuver legality classification using state-of-the-art video action recognition backbones (CNN and Transformer-based), extended with multimodal fusion, and find that combining RGB, gaze, and telemetry consistently yields the best performance. MOTOR thus provides a unique foundation for advancing safety-critical understanding of two-wheeler riding. It offers the research community a benchmark to develop and evaluate models for behavior analysis, legality-aware prediction, and intelligent transportation systems. Dataset and code is available at https://varuniiith.github.io/MOTOR-Dataset/", "published": "2026-11-14", "comment": null, "url": "https://arxiv.org/abs/2605.22550"}, {"id": "2607.12818", "title": "Breaking Déjà Vu: Independent Auditing of Visual Place Recognition through Vision-Language Reasoning", "authors": ["Sania Waheed", "Michael Milford", "Sarvapali D. Ramchurn", "Shoaib Ehsan"], "abstract": "Visual place recognition (VPR) is a key enabler of accurate localization and long-term autonomous navigation in robotics applications, such as loop closure detection for simultaneous localisation and mapping (SLAM). However, real-world VPR deployment relies on selecting an image matching threshold that balances precision and recall. These thresholds are typically tuned using labeled validation data and fixed during deployment, making them unreliable under environmental changes where ground truth is unavailable. This is particularly problematic in safety-critical robotics, where accepting a false loop closure can corrupt the estimated trajectory and map. In this work, we introduce Visual Place Recognition Auditing, an independent post-retrieval verification framework that leverages Vision-Language Models (VLMs) to assess retrieved matches by reasoning jointly over query and candidate images. Unlike conventional verification methods, our approach performs instance-level verification without requiring architecture-specific confidence measures, dataset-dependent thresholds, or prior knowledge of the deployment environment. We evaluate our method on six benchmark datasets using five state-of-the-art VPR methods and four VLMs. Results show that VLM-based auditing improves recall@1 by 13.6% on average as compared to state-of-the-art methods while reducing false acceptance rates to 12%, maintaining precision above 95% and coverage above 75%.", "published": "2026-11-14", "comment": null, "url": "https://arxiv.org/abs/2607.12818"}, {"id": "2611.19095", "title": "DEFDVO: Deformable Deep Visual Odometry for Equirectangular Images", "authors": ["Burak Sevsay", "Egor Bondarev", "Erkut Akdag"], "abstract": "Omnidirectional ($360^\\circ$) cameras capture the full surrounding scene in every frame, providing a strong advantage for visual odometry (VO) over pinhole sensors with a limited field of view. However, their equirectangular projection (ERP) introduces latitude-dependent distortion, an artificial seam at the image border, and a sampling bias toward the poles. Existing $360^\\circ$ VO methods address these challenges only partially. DEFDVO closes this gap with a patch-based deep VO method that operates directly on ERP imagery, combining spherically initialized deformable feature extraction, end-to-end seam-aware estimation, and spherical-gradient patch selection. The deformable feature extractor combines spherical geometric priors with learned sampling offsets, while seam-aware processing preserves ERP continuity, and spherical-gradient selection reduces polar sampling bias. Trained exclusively on synthetic TartanAirV2 ERP imagery, DEFDVO improves the best prior average absolute trajectory error (ATE) by $4.8\\times$ (0.201 m to 0.042 m) on the TartanAirV2 evaluation set defined by 360DVO and achieves the lowest average ATE on both splits of the real-world 360DVO benchmark. Code is available at https://github.com/BurakSevsay/DEFDVO", "published": "2026-11-14", "comment": "Accepted to WACV 2027", "url": "https://arxiv.org/abs/2611.19095"}, {"id": "2510.00524", "title": "Two stage GNSS outlier detection for factor graph optimization based GNSS-RTK/INS/odometer fusion", "authors": ["Baoshan Song", "Penggao Yan", "Xiao Xia", "Yihan Zhong", "Yuan Li", "Weisong Wen", "Li-Ta Hsu"], "abstract": "GNSS pseudorange outliers severely disturb carrier-phase ambiguity resolution and positioning, particularly during signal blockages and recovery. Temporal Doppler consistency provides a reliable short-term range-change reference, but requires valid measurements at both endpoints and becomes unavailable upon signal re-acquisition. This paper presents a two-stage pseudorange screening framework that complements Doppler consistency with joint IMU-odometer motion prediction. The second stage compares predicted and measured temporal changes of double-differenced pseudoranges against an accepted anchor epoch without using current GNSS observations in the motion reference. A first-order error model separates anchor, relative-motion, and measurement uncertainties to propagate factor-graph covariance into the chi-square detection gate, and both stages adjust code weights through a closed-form minimum-inflation rule. Under continuous tracking, Doppler screening reduces RTK 3D RMSE by 96.18% and outperforms the a-contrario baseline by 58.56%. When Doppler checks are unavailable, joint IMU-odometer prediction detects a 10-m outlier change in 99.58% of trials after 30 s and 73.72% after 60 s, reducing RIO 3D RMSE by up to 78.51% after outages while RI screening outperforms an inertial-aided baseline by 70.42% in simulation and 39.11% in deep urban canyons.", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2510.00524"}, {"id": "2601.15549", "title": "VIOLA: Towards Video In-Context Learning with Minimal Annotations", "authors": ["Ryo Fujii", "Hideo Saito", "Ryo Hachiuma"], "abstract": "Generalizing Multimodal Large Language Models (MLLMs) to novel video domains is essential for real-world deployment but remains challenging due to the scarcity of labeled data. While In-Context Learning (ICL) offers a training-free adaptation path, standard methods rely on large annotated pools, which are often impractical in specialized environments like industrial or surgical settings since they require the experts' annotations. To bridge this gap, we introduce VIOLA (Video In-cOntext Learning with minimal Annotation), a label-efficient framework that synergizes minimal expert supervision with abundant unlabeled data. First, to maximize the efficiency of a strict annotation budget, we propose density-uncertainty-weighted sampling. Unlike standard diversity or uncertainty strategies that risk selecting visual outliers, our method leverages density estimation to identify samples that are simultaneously diverse, representative, and informative. Second, to utilize the remaining unlabeled data without noise propagation, we construct a hybrid pool and introduce confidence-aware retrieval and confidence-aware prompting. These mechanisms explicitly model label reliability, retrieving demonstrations based on a composite score of similarity and confidence while enabling the MLLM to adaptively distinguish between verified ground truths and noisy pseudo-labels. Extensive experiments across nine diverse benchmarks using three MLLMs demonstrate that our framework significantly outperforms various baselines in low-resource settings, achieving robust adaptation with minimal annotation costs. Project page: https://fujiry0.github.io/VIOLA-project-page/", "published": "2026-11-15", "comment": "Accepted to WACV 2027 (Round 1)", "url": "https://arxiv.org/abs/2601.15549"}, {"id": "2608.13856", "title": "Optical GeoAI and spatial modeling enable urban-canopy mapping and resilience screening in Davis, California", "authors": ["Mohammadreza Narimani", "Shreyan Mitra", "Parastoo Farajpoor"], "abstract": "Timely urban-canopy information is essential for linking remote sensing with heat, mobility, and neighborhood planning. We developed an optical GeoAI workflow for Davis, California, using 2022 National Agriculture Imagery Program imagery (0.6 m RGB+NIR). DeepForest generated crown candidates; an NDVI threshold, non-maximum suppression, and box-prompted Segment Anything Model (ViT-B) produced a crown-anchored canopy surface. Analyses used the 25.92 km2 Census TIGER municipal boundary and a 100 m grid. The workflow retained 11,741 candidate crowns and mapped 7.71 km2 of canopy (29.8% of the city). On the identical extent, pixel precision was 0.804, pixel recall was 0.873, and 97.4% of candidate centers agreed with the 2022 USDA/CAL FIRE LiDAR-assisted canopy product (IoU 0.719; Dice 0.837; area recovery 108.5%). Approximately 49% of candidates occurred within 15 m of a road. Canopy was inversely associated with Landsat land-surface temperature (Spearman rho = -0.477; partial rho = -0.551 controlling for built probability), and spatial-lag modeling confirmed clear neighborhood structure. Two transparent attention surfaces combined canopy need with thermal and contextual indicators. The framework provides a reproducible, updateable screening layer that complements structural canopy products and municipal inventories while retaining assumptions, data provenance, and spatial diagnostics for planning interpretation.", "published": "2026-11-15", "comment": "17 pages, 10 figures + 5 supplementary figures, 7 tables. Revised preprint (expanded canopy infill; IoU 0.719). Preprint submitted to Frontiers. Code: https://github.com/MohammadrezaNarimaniUCDavis/Davis_Urban_Canopy_GeoAI Data: https://doi.org/10.5281/zenodo.21925526", "url": "https://arxiv.org/abs/2608.13856"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2611.21253", "title": "QuantileGS: Quantile-Based Conformal Bounds on RGB Rendering Errors for Novel View Synthesis with 3D Gaussian Splatting", "authors": ["Haiyang Xu", "Ziye Zhang", "Bin Pan", "Xia Xu", "Zhenwei Shi"], "abstract": "Uncertainty quantification for novel view synthesis with 3D Gaussian Splatting (3DGS) assesses rendering reliability at unseen viewpoints. This reliability depends on the discrepancy between rendered and true colors, which cannot be measured without ground-truth images. We therefore quantify uncertainty in this unknown discrepancy through upper bounds on per-pixel RGB mean absolute error. However, learned bounds may underestimate these errors and overstate rendering reliability, motivating calibration to a prescribed coverage level. In this paper, we propose QuantileGS, a post-hoc framework that combines learned rendering-error quantiles with scale-normalized conformal calibration to produce spatially adaptive error bounds. The framework comprises three phases. Phase 1, Rendering-Error Computation, measures RGB mean absolute error between observed images and predictions from a frozen 3DGS model. Phase 2, Ordered Gaussian Quantile Fields, learns two scalar attributes per Gaussian to predict lower and upper rendering-error quantiles. Phase 3, Scale-Normalized Conformal Calibration, calibrates the upper prediction on held-out images, using the quantile gap to scale the correction. Under the stated assumptions, the resulting bounds provide finite-sample marginal coverage. At a nominal coverage level of 90%, calibration raises mean empirical test coverage from 69.6% to 89.6% on LLFF and from 80.1% to 92.1% on Mip-NeRF 360. On LF, coverage remains conservative at 96.3% before and 96.4% after calibration. Applications to active view selection, Gaussian pruning, and RGB-D simultaneous localization and mapping illustrate how these bounds inform downstream decisions.", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2611.21253"}, {"id": "2603.09632", "title": "X-GS: An Extensible Framework for Perceiving and Thinking with 3D Gaussian Splatting", "authors": ["Yueen Ma", "Zenglin Xu", "Irwin King"], "abstract": "3D Gaussian Splatting (3DGS) has emerged as a powerful technique for novel view synthesis, subsequently extending into numerous spatial AI applications. However, most existing 3DGS methods operate in isolation, focusing on specific domains. In this paper, we introduce X-GS, an extensible framework that integrates previously isolated 3DGS methods into the perception module of a VLM for spatial tasks, with two major components: the $\\textit{Perceiver}$ and the $\\textit{Thinker}$. The $\\textit{Perceiver}$ performs online 3DGS-based SLAM with semantic distillation and outputs semantic Gaussians from unposed video streams. It leverages recent vision foundation models for stronger geometric priors, and we introduce three novel optimizations to improve semantic distillation efficiency. The $\\textit{Thinker}$ interfaces diverse VLMs with these semantic Gaussians, unlocking spatial multimodal capabilities such as 3D visual grounding and scene captioning. Experimental results on diverse benchmarks demonstrate the efficiency and newly unlocked multimodal capabilities of the X-GS framework. Code is available at https://github.com/yueen-ma/X-GS.", "published": "2026-11-16", "comment": "16 pages, 5 figures. Accepted to Findings of EMNLP 2026", "url": "https://arxiv.org/abs/2603.09632"}, {"id": "2508.18694", "title": "AgriChrono: A Longitudinal Dataset and Benchmark for Novel-View Synthesis of Field-Grown Crops", "authors": ["Jaehwan Jeong", "Tuan-Anh Vu", "Mohammad Jony", "Shahab Ahmad", "Md. Mukhlesur Rahman", "Sangpil Kim", "M. Khalid Jawed"], "abstract": "Reliable 3D reconstruction of field-grown crops is hindered by thin, overlapping structures, wind-driven foliage motion, and changing illumination. Yet longitudinal field datasets and standardized novel-view synthesis (NVS) benchmarks remain scarce. We present an integrated framework for robotic acquisition, dataset construction, NVS evaluation, and agricultural scene reconstruction. AgriChrobot enables web-based teleoperation and repeated multi-view capture along crop rows. Using this platform, we introduce AgriChrono, a longitudinal canola dataset collected over approximately one month, comprising 160 recording sessions, four RGB streams, two depth maps, and estimated camera poses. We define seven NVS scenarios spanning four times of day and three acquisition dates, and benchmark 15 NeRF- and Gaussian Splatting-based methods. In addition to whole-image metrics, we assess fine-detail reconstruction within manually annotated canola regions using gradient- and edge-based metrics. Our results show that strong whole-image scores do not guarantee faithful reconstruction of thin, overlapping crop structures. To address this gap, we propose AgriSplat, which relaxes visibility filtering during initialization and reallocates model capacity through contribution-based pruning and budgeted reinvestment in sub-threshold candidates ranked by existing gradient statistics. After reallocation, asymmetric directional supervision penalizes insufficient contrast along reference image-gradient directions. Relative to Octree-GS, AgriSplat improves mean crop-region gradient-energy ratio from 0.506 to 0.847 and edge F-score from 0.712 to 0.797 across seven scenarios, while also improving whole-image PSNR, SSIM, and LPIPS. These contributions provide a dataset, benchmark, and method for systematic crop reconstruction under field conditions.", "published": "2026-11-14", "comment": "Keywords: Agricultural robotics, Multimodal dataset, Longitudinal crop monitoring, Illumination variability, 3D Gaussian Splatting, Novel view synthesis, 3D Reconstruction", "url": "https://arxiv.org/abs/2508.18694"}, {"id": "2611.02658", "title": "OctreeSplat: Hierarchical Octree-Guided Feed-Forward Gaussian Splatting", "authors": ["Yibin Zhao", "Yihan Pan", "Wenli Yang", "Jun Nan", "Jianjun Yi"], "abstract": "Recent feed-forward 3D Gaussian Splatting (3DGS) methods typically regress pixel-aligned Gaussian primitives, often causing excessive overlap and artifacts, while inaccuracies in predicted camera poses can lead to misalignment in novel-view synthesis (NVS). We present VoxelTTO, a feed-forward framework for reconstructing geometrically accurate 3DGS from an arbitrary number of images and optional camera parameters. VoxelTTO aggregates dense image features into global voxels and decodes Gaussians from voxel features, breaking the pixel-to-Gaussian correspondence. To exploit known camera parameters while keeping the pretrained visual foundation model (VFM) parameters frozen, we introduce test-time optimization (TTO) that adapts lightweight LoRA modules using pose supervision. We further replace vanilla 3DGS rasterization with stochastic solid volume rendering during training and inference, improving geometric fidelity. Training updates only the voxel-aligned Gaussian reconstruction modules, requiring 80 GPU hours. Experiments on Replica, Tanks and Temples, RE10K, and DTU demonstrate improved RGB-D NVS and camera-pose alignment relative to prior methods.", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2611.02658"}, {"id": "2611.19773", "title": "SemLite-GS: Semantic-Selective Parallel Gaussian Splatting for Lightweight Building Reconstruction from UAV Oblique Imagery", "authors": ["Tengfei Wang", "Xin Wang", "Zihan Li", "Quanjian Ji", "Yifei Yu", "Dong Lin", "Zongqian Zhan"], "abstract": "Lightweight 3D building models support urban spatial analysis, but their production often requires dense scene reconstruction, building extraction, and mesh simplification. Although 3D Gaussian Splatting (3DGS) is more efficient than conventional multi-view stereo, existing large-scale methods lack semantic selection and parallel instance-level training. We present SemLite-GS, a building-centric framework that reconstructs lightweight building meshes from large-scale UAV oblique imagery. First, an orthographic reference map establishes globally consistent building identities, which are propagated to oblique views to form camera-instance pairs and regions of interest. Second, semantic-selective parallel PGSR training jointly processes multiple pairs within relevant image regions while updating only target Gaussians; contextual Gaussians remain fixed to preserve visibility. Third, architectural planes extracted from rendered depth, opacity, and normal maps guide signed distance field optimization, producing meshes with adaptive polygon allocation and well-defined structural boundaries. Experiments on multiple large-scale UAV datasets demonstrate that our SemLite-GS substantially reduces building reconstruction time compared with representative full-scene 3DGS methods. With comparable polygon budgets, SemLite-GS achieves superior preservation of dominant planar structures and sharp architectural transitions compared with conventional dense reconstruction followed by mesh decimation. The source code is available at https://github.com/IRIS-LAB-whu/SemLite-GS.", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2611.19773"}, {"id": "2611.19429", "title": "Prepare Lighter and Faster for Open-Vocabulary Queries: A Query-Wise 3D Segmenter for Gaussian Splatting", "authors": ["Nhat-Quynh Le-Pham", "Khoi Nguyen", "Binh-Son Hua"], "abstract": "Open-vocabulary 3D understanding aims to localize and segment arbitrary objects beyond predefined categories. However, existing approaches based on Gaussian Splatting often rely on expensive preprocessing and lengthy training, limiting their applicability when fast and lightweight solutions are desired. We propose a lightweight, training-free framework for query-driven 3D instance segmentation on Gaussian Splatting. Instead of conventional mask-wise CLIP embeddings, we use dense pixel-level CLIP features to preserve fine-grained semantic information and enable flexible text-driven localization without relying on predefined instance proposals. Given a text query, we identify a high-quality target region in a carefully selected pivot view and propagate it across views using a video segmentor, providing consistent and comprehensive coverage of the target instance. We then lift the resulting 2D tracklets to 3D Gaussians through a novel visibility voting strategy, yielding accurate 3D segmentation masks with clean object boundaries. Extensive experiments demonstrate state-of-the-art performance on LERF-OVS, ScanNet, and ScanNet++, competitive results on 3D-OVS, and significant speedups over existing open-vocabulary 3D segmentation methods. These results highlight the effectiveness of our framework for efficient open-vocabulary 3D understanding without per-scene training.", "published": "2026-11-14", "comment": "Accepted at WACV 2027", "url": "https://arxiv.org/abs/2611.19429"}, {"id": "2611.18267", "title": "TetraCoder: Adaptive Tetrahedral Encoding for Neural Fields", "authors": ["Daniele Della Pietra", "Antonella Rech", "Nicola Conci", "Nicola Garau"], "abstract": "Implicit and explicit representations of geometry are central in computer graphics applications and come with their pros and cons. With surface sampling being faster on explicit representations and spatial queries being faster on implicit representations, finding efficient conversions between them is a highly desirable property. We present TetraCoder, a single resolution hash-free adaptive tetrahedral encoding that links an explicit tetrahedral spatial encoder with an underlying implicit signed distance field (SDF). The resulting hybrid implicit-explicit space is continuous piecewise affine (CPWA) by design, allowing to obtain an exact correspondence between the implicit SDF and the explicit analytic mesh. TetraCoder's design comes with additional perks, in particular: (a) it scales better than multi-resolution encoding methods due to its single resolution optimizable grid, (b) unlike hash-based methods, it is not affected by collisions, (c) it enables fast tetrahedral ray-tracing, geometry and appearance editing, directly through its adaptive tetrahedral scaffold. We demonstrate the versatility of TetraCoder by showing an improvement over state-of-the-art methods on multiple tasks: 2D/3D fitting from images and point clouds, 3D novel view synthesis, 3D reconstruction, and geometry/appearance editing.", "published": "2026-11-16", "comment": "8 pages, 4 figures", "url": "https://arxiv.org/abs/2611.18267"}, {"id": "2607.03875", "title": "MACRO: Training-free Multi-plane Attention for Closeup Render Optimization", "authors": ["Nitzan Hodos", "Roy Amoyal", "Lior Fritz", "Ianir Ideses", "Sagie Benaim", "Netalee Efrat"], "abstract": "Close-up rendering, zooming into a scene well beyond any training camera, is important for virtual production and interactive 3D content, yet remains an open challenge. 3D Gaussian splatting (3DGS) enables high-fidelity, real-time novel view synthesis, but its rendering quality degrades at close range. Recent diffusion-based methods that enhance the rendering by conditioning on reference images from the training set produce significant artifacts in this setting. We analyze this failure and identify its root cause: the scale gap between the close-up and reference views. We show that the features in reference-conditioned enhancement models are not scale-invariant, causing cross-view attention to retrieve incorrect correspondences when the same content appears at different scales, and that this mismatch cannot be corrected in latent space because the VAE encoder is not scale-equivariant. Building on this analysis we introduce MACRO, Multi-plane Attention for Closeup Render Optimization, a training-free method for high-quality close-up novel view synthesis from 3DGS. MACRO resolves the scale gap by leveraging the scene's known 3D structure: it decomposes the close-up into depth planes, crops and resizes references in image space to match the scale of each plane before encoding, and applies a depth-aware attention mask so each token attends only to scale-matched references. The method requires no architectural changes or additional training. We further contribute two new close-up novel view synthesis benchmarks, the first standardized evaluation protocol for this setting, and demonstrate state-of-the-art results on both, outperforming existing 3DGS and diffusion-based methods on both reconstruction and perceptual metrics. Project page: https://nitzanhod.github.io/MACRO", "published": "2026-11-14", "comment": "Project page: https://nitzanhod.github.io/MACRO", "url": "https://arxiv.org/abs/2607.03875"}, {"id": "2609.06948", "title": "PRG-Fusion: Orchestrating Generative Priors with Reconstruction Evidence for Driving View Synthesis", "authors": ["Sipeng He", "Jialei Chen", "Zhen Fang", "Dongchun Ren", "Feng Zhao"], "abstract": "Synthesizing photorealistic driving videos along specified trajectories is essential for scalable closed-loop simulation. However, reconstructed scenes exhibit spatially varying degradation under viewpoint shifts, while generative refinement can alter reliable content and introduce geometric inconsistencies. We propose \\mbox{\\textbf{PRG-Fusion}}, a framework for driving view synthesis that uses reconstruction evidence to orchestrate generative priors across regions. Our key insight is that reconstruction reliability and available support should jointly determine how previously unseen regions are generated and reliable content is preserved. We derive pixel-wise Preserve, Repair, and Generate (PRG) labels from reconstruction evidence to distinguish reliable appearance, degraded but supported content, and regions with insufficient support. At inference, these labels serve as a unified routing policy for region-aware spatiotemporal synthesis, orchestrating 3DGS appearance preservation, LiDAR-guided structural correction, and video-prior-driven content completion across Preserve, Repair, and Generate regions, respectively. We then follow a two-stage training paradigm, first establishing geometric control from sparse LiDAR projections and subsequently learning appearance control from dense 3DGS renderings. Extensive experiments on Waymo demonstrate that \\mbox{\\textbf{PRG-Fusion}} achieves state-of-the-art overall performance in novel trajectory video synthesis, with superior visual quality and geometric fidelity while maintaining competitive view consistency under large trajectory shifts. Our project page is available at https://pre-cici.github.io/PRG-Fusion/", "published": "2026-11-14", "comment": null, "url": "https://arxiv.org/abs/2609.06948"}, {"id": "2611.19409", "title": "SplatFlow3D: Learning Scene Flow via 3D Motion Feature Splatting", "authors": ["Bo Wang", "Dekang Zhu", "Jian Li", "Zhipeng Meng", "Bo Wang", "Dewen Hu"], "abstract": "Considering the motion continuity and stability of 3D objects over short inter-frame intervals, introducing multi-frame settings in scene flow estimation can potentially address occlusion. In this paper, we propose a two-frame backbone, SimpleFlow3D, which integrates dense information from the image plane and sparse information from the depth dimension in a decoupling-followed-by-coupling manner by hierarchically constructing the 3D motion feature. SimpleFlow3D achieves SOTA results with minimal parameters. We also propose a weight-sharing multi-frame framework to splat the previous 3D motion feature to the current estimation process. The framework unifies the first and non-first frame inference by constructing pseudo inputs. After combining the proposed framework and backbone, the newly born multi-frame method SplatFlow3D further advances the state of the art. It achieves lower errors than the two-frame backbone, with fewer parameters than current methods. On both KITTI and Spring, SplatFlow3D ranked 1st over all published and submitted methods. Experiments show that SplatFlow3D improves occlusion handling, non-rigid motion estimation, and generalization to real-world scenes. Code is available at https://github.com/wwsource/SplatFlow3D.", "published": "2026-11-14", "comment": null, "url": "https://arxiv.org/abs/2611.19409"}, {"id": "2611.19640", "title": "Floorplan-Context-Aware Cross-Environment Human Activity Recognition from mmWave Radar Point Clouds", "authors": ["Zixiong Han", "Xilai Wang", "Chenzhe Zhao", "Amr Mourad", "Miodrag Bolic"], "abstract": "Human activity recognition (HAR) models based on mmWave radar point clouds and trained in controlled open spaces often experience performance degradation when deployed in furnished rooms. We propose a Floorplan-Context-Aware (FCA) HAR enhancement method that augments the input with subject-furniture relative position information to improve cross-environment performance. Because existing mmWave point-cloud datasets lack registered floorplans, we introduce a pseudo-landmark augmentation strategy for training the FCA model. In cross-environment evaluation on the mm-ADL-Home dataset, FCA achieves 77.70% accuracy and 65.49% macro-F1, improving upon the point-cloud-only direct-transfer baseline by 10.73 and 10.05 percentage points, respectively, and exceeding the strongest evaluated adaptation baseline by 7.37 and 6.27 percentage points. At deployment, FCA requires only a one-time registration of furniture landmarks, with no target-domain activity annotations or model weight updates.", "published": "2026-11-14", "comment": "Submitted to ICASSP 2027", "url": "https://arxiv.org/abs/2611.19640"}, {"id": "2610.20585", "title": "Learnable Hodge-Laplacian Driven Mixture of Experts for Steady-PDE Surrogates on Coarse Unstructured Meshes", "authors": ["Stavros Nousias", "Akis Nousias", "Konstantinos Gkrispanis"], "abstract": "Surrogate models approximate the solutions of partial differential equations (PDEs) for given geometries and boundary conditions. Conventional Transformer-based approaches typically employ a common feature-mixing mechanism across the solution domain, despite the presence of spatial variations at different scales. In this paper, we propose a mixture of transformer experts that combines a routing mechanism with multiscale supervision. Specifically, the individual experts are routed through a controller that utilizes learnable Laplacian matrices to compute weights, used to define a weighted sum of the experts for the output feature vectors at each point of the domain. Subsequently, a decoder receives the weighted sum of the experts output and predicts the solution fields. During training, the reference fields are decomposed into components at different spatial scales by repeated smoothing with a mesh Laplacian. We evaluate our approach on the official AirFRANS dataset using remeshed solution domains leading to unstructured triangular meshes of $4.9$k vertices. The experimental outcomes reveal lower mean relative $L_2$ error and interior mean squared errors among the compared models of this study. Code and data are publicly available in https://github.com/snousias/hodge-moe-pde", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2610.20585"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2611.21302", "title": "Déjà-Events: Multi-view 3D Geometry with Event Cameras via Sparsity-Aware Adaptive Gating", "authors": ["Arda Cinar Demirtas", "Pablo Varela Bernal", "Marc Pollefeys", "Sunghwan Hong"], "abstract": "Event cameras keep capturing structure where conventional cameras blur or saturate, which makes them attractive for 3D perception in fast or poorly lit scenes. Event datasets with dense 3D ground truth, however, are far smaller and less diverse than the image collections behind feed-forward 3D reconstruction models. We present Déjà-Events, an event-only model that predicts depth, camera pose and pointmaps from multiple views in a single forward pass. Rather than relying on scarce 3D labels, we distil it from Déjà View, a feed-forward RGB model that refines its tokens by repeatedly applying one shared transformer block. On paired RGB and event recordings, the event student learns to reproduce the frozen teacher's final tokens, which requires no depth or pose ground truth and trains only about 1% of its parameters. Because events are dense at edges and moving texture but nearly absent in textureless regions, we further introduce sparsity-aware adaptive gating, which adapts the shared block's gates to events and adjusts them per patch by event density, so that accuracy holds as refinement steps are added. Trained only on simulated data, Déjà-Events achieves the lowest pointmap error among the event-based methods we evaluate, on EventScape and zero-shot on the real MVSEC and DSEC datasets. On DSEC it halves the error of the strongest baseline (0.15 vs. 0.30 AbsRel) with about a tenth of its parameters. It also has the lowest depth error on EventScape and DSEC and the lowest trajectory error on EventScape.", "published": "2026-11-16", "comment": "8 pages, 6 figures", "url": "https://arxiv.org/abs/2611.21302"}, {"id": "2611.18099", "title": "Eco3R: Pinned-Key Inference for Efficient and Streamable Feed-Forward 3D Reconstruction from Long Videos", "authors": ["Hongsen Cao", "Shanxin Yuan", "Mona Jaber", "Ahmed Sayed"], "abstract": "Feed-forward multi-view transformers such as VGGT recover the cameras and geometry of a video in one pass, but the cost of their cross-frame self-attention grows quadratically with the frame count, and their accuracy drops on long videos. Most remedies approximate attention over all frames under a fixed computational budget or select a few keys by their content. We hypothesize that the keys of a long video can be selected independently of video content, and our experiments on VGGT and $π^3$ support it: a small number of uniformly sampled frames can serve as the keys of every frame. We present Eco3R, a training-free inference framework whose keys form a Pinned Key Set of 31 such frames. A pin pass stores their tokens in a Scene Cache, and the other frames read it in independent batches that reproduce joint inference with these keys exactly, at a constant cost per frame. An Online Stream updates the pinned frames during recording. Six middle global blocks align the frames and form a reusable VGGT module: the Alignment Score reads their attention to flag failures, and Alignment Refocusing reduces them by fine-tuning only these blocks (3.6 GPU hours). Eco3R ($π^3$) matches $π^3$'s success rate on 1,000-frame ScanNet videos while running 13.8 times faster. With refocusing, Eco3R (VGGT) raises VGGT's success rate from 70% to 82% while running 8.5 times faster on 500 frames. Eco3R can reconstruct sequences of up to 4,000 frames on a single A100 GPU, while Eco3R ($π^3$) streams 1,000 frames at 18.6 fps, achieving the lowest online absolute trajectory error.", "published": "2026-11-16", "comment": "26 pages, 10 figures. v2: renamed the method from EcoVGGT to Eco3R, added Figure 1, and revised the text", "url": "https://arxiv.org/abs/2611.18099"}, {"id": "2611.21126", "title": "IGRecon4D: Dynamic-Object-Aware Feed-Forward Reconstruction of Driving Scenes", "authors": ["Yifei Tong", "Ziyang Huang", "Yizhao Han", "Xiaoxiao Long", "Hao Zhu"], "abstract": "Feed-forward 4D driving-scene reconstruction enables efficient modeling of dynamic autonomous-driving scenes, but current methods suffer from two complementary failure modes: semantic leakage of traffic participants into the static representation and geometric drift of Gaussian locations across viewpoints. We propose \\textbf{IGRecon4D}, a feed-forward dynamic scene reconstruction framework that addresses these failures with training-time instance-prior distillation and LiDAR-anchored Gaussian positioning. Specifically, an instance-level semantic branch provides a potentially dynamic participant prior, which is distilled into dynamic-mask learning through the Instance-Dynamic Consistency Constraint to encourage high-recall localization of traffic-participant regions prone to dynamic-static leakage. In parallel, sparse LiDAR measurements guide dense depth estimation, and the resulting depths are back-projected to anchor Gaussian positions for improved multi-view geometric consistency. Experiments on the Waymo Open Dataset and zero-shot evaluation on nuScenes demonstrate improved full-image reconstruction on the main benchmark and stronger traffic-participant-region reconstruction under cross-dataset evaluation.", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2611.21126"}, {"id": "2611.19179", "title": "Isolating Perception for Multi-View Planning under Occlusion-Induced Partial Observability", "authors": ["Kevin Nguyen", "Ceyhun Efe Kayan", "Feng Liu", "Li Zhang"], "abstract": "Vision-language models (VLMs) are beginning to saturate visual planning benchmarks, yet they fail to resolve depth ambiguity and degrade sharply with problem size under occlusion-induced partial observability (PO). We introduce BW-PO based on the Blocksworld domain, a controlled benchmark that reduces existing VLM planners and formalizers to near-zero performance, and propose VLM-as-perceiver, a paradigm that narrows the VLM's role to local perception while delegating cross-view evidence reconciliation and plan generation to external solvers. Across model-specific challenging subsets of BW-PO, this raises plan success from 1% to 97% for Gemma-4-31B, 0% to 95% for Qwen3.5-122B-A10B, and 3% to 84% for Gemini-3.1-Pro. Isolating perception in this way separates two bottlenecks that are otherwise entangled: reconciliation under depth ambiguity, and completeness of visual extraction under scene density.", "published": "2026-11-14", "comment": "EACL 2027", "url": "https://arxiv.org/abs/2611.19179"}, {"id": "2611.20025", "title": "acuSimNet: Multi-View Self-Occlusion-Awared Visibility Learning for Cranio-Cervical Acupuncture Points", "authors": ["Jiatao Ma", "Qilei Sun"], "abstract": "The localization of acupuncture points (acupoints) in Traditional Chinese Medicine (TCM) presents unique challenges since they are defined by abstract principles rather than distinct anatomical landmarks. Existing approaches are typically constrained to single view or rely on indirect calculations of relative positions with respect to other landmarks, thereby overlooking human anatomical variations. Furthermore, acupoint visibility assessment, which determins whether points are occluded by human itself, hair, clothing, or other objects, has received limited attention in practical applications. Acupoint localization itself does not require 3D reconstruction, but inferring their occlusion relationships with anatomical surfaces does, which adds computational cost and limits real-time inference. In this work, we introduce acuSimNet, an efficient hierarchical multi-task learning architecture for multi-view, self-occlusion-aware visibility prediction of acupoints, achieving 99.97% accuracy on the validation set. Our approach also addresses the challenges of high-dimensional classification (174 acupoints in cervicocranial region), negative convergence issues for visible acupoints, and inter-task scheduling optimization, resulting in substantially accelerated convergence. We improved the training efficiency from the exisiting methods of 3000 epochs to achieve 99% validation accuracy, to our optimized framework achieving 90% accuracy in 39 epochs and 99% accuracy in 86 epochs. This architecture overcomes the limitations of existing methods, could enable practical applications in acupoints detection and visualization, advancing the automation of TCM.", "published": "2026-11-15", "comment": "19 pages, 6 figures, 3 tables", "url": "https://arxiv.org/abs/2611.20025"}, {"id": "2611.20425", "title": "InterRSGaussian: Interactive Multi-view Instance Segmentation for 3D Remote Sensing Scenes", "authors": ["Zipeng Qi", "Zhengxia Zou", "Zhenwei Shi"], "abstract": "Remote sensing image segmentation plays a critical role in various applications. Interactive instance segmentation, a specialized task within image segmentation, aims to generate precise segmentation results for target objects based on user input prompts. However, previous studies on interactive instance segmentation primarily focus on single-view images, limiting their ability to comprehensively understand complex 3D remote sensing scenes. In this study, we extend interactive instance segmentation from a single-view to a multi-view framework, which can also be easily converted to a 3D segmentation format, thus achieving more accurate and comprehensive 3D remote sensing scene perception across multiple views. First, we construct a multi-view interactive instance segmentation dataset for remote sensing, comprising five distinct scenes, each captured from about one hundred different views. Second, we propose InterRSGaussian, a novel instance segmentation method based on 3D Gaussians. InterRSGaussian enables users to provide point clicks on target objects from any arbitrary view and generates view-consistent instance segmentation results across all input views without requiring manual annotations. The resulting multi-view segmentation can further be projected onto 3D point clouds for 3D segmentation. To improve training efficiency and segmentation performance, we introduce a prior distillation network for initialization. Overall, this study extends traditional 2D remote sensing scene perception into a 3D multi-view framework, enabling a more comprehensive understanding of target objects in complex environments with user interactivity.", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2611.20425"}, {"id": "2611.20703", "title": "Efficient Multi-View Generation with Iterative Global-Local Proxy Attention", "authors": ["Wei Tan", "Kunming Luo", "Hongyu Yan", "Yu Zhang", "Zihao Zhang", "Xiatian Zhu", "Lei Xie"], "abstract": "Generating consistent multi-view RGB images and normal maps from a single input image provides complementary appearance and geometric cues for 3D reconstruction. However, maintaining cross-view consistency requires information exchange across viewpoints, and dense cross-view attention becomes computationally expensive as the number of views and spatial resolution increase. In this paper, we propose Global-Local Proxy Attention (GLPA) to reduce cross-view communication costs while preserving fine-grained within-view processing. Specifically, GLPA retains full-resolution interactions within each view and uses compact global proxies for cross-view communication. To further leverage the exchanged information, GLPA incorporates iterative proxy refinement, which rebuilds the proxies from updated features and reuses the same attention parameters for subsequent interactions within a single denoising step. We evaluate GLPA on two structurally different diffusion backbones, FLUX and Stable Diffusion. Experiments on FLUX show that GLPA achieves a $2.65\\times$ speedup in attention computation per denoising step over dense attention, while improving reconstruction IoU from 0.6849 to 0.7019 and reducing NVS LPIPS from 0.086 to 0.076. Results on Stable Diffusion further demonstrate the effectiveness of GLPA, with a $1.80\\times$ attention speedup and improvements across all five quality metrics.", "published": "2026-11-16", "comment": "10 pages, 6 figures, 5 tables. Supplementary material is available as an ancillary file", "url": "https://arxiv.org/abs/2611.20703"}, {"id": "2611.20872", "title": "MVSTF: Multi-View Spatio-Temporal Fusion for LiDAR-Based Moving Object Segmentation", "authors": ["Jiaoju Zhou", "Chao Ye", "Xuebo Yang", "Weiyang Lin"], "abstract": "Autonomous mobile robots confront significant chal lenges in recognizing the motion properties of objects in dy namic environments. However, existing methods are hindered by limitations such as boundary ambiguity, occlusion, viewpoint constraints, and training complexity. In this paper, we propose an innovative end-to-end Multi-View Spatio-Temporal Fusion network, named MVSTF, which utilizes sequential point clouds to generate multi-view images and feature differences, and designs a multi-branch network to extract spatio-temporal and dimen sional features in parallel, and realizes high-precision moving object segmentation. First, sequential point clouds are utilized to generate multi-view images and feature differences. Then, an end-to-end multi-branch network including Dual Down-sampling Blocks (DDB), Spatial Attention Blocks (SAB), Multi-Kernel Convolutional Neural Network blocks (MKCNN), Dual Feature Fusion Blocks (DFFB), and the Point Fusion (PF) module, is designed to extract motion features from feature differences and geometric and semantic features from multi-view images. Finally, an auxiliary semantic head is introduced to further improve the algorithm's robustness and the model's interpretability. This work is validated on the SemanticKITTI and KITTI-Road bench marks, achieving state-of-the-art results on the SemanticKITTI MOS validation set and the KITTI-Road validation set, and competitive results on the hidden SemanticKITTI-MOS test set. The code is available at https://github.com/ZhouJJ111/MVSTF.", "published": "2026-11-16", "comment": null, "url": "https://arxiv.org/abs/2611.20872"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2611.19771", "title": "JEPA4R: Embodied JEPA World Models with 4D Point Planning", "authors": ["Jiarui Dong", "Zhiheng Liang", "Yanjun Li", "Zeyu Zhang", "Heejeong Nam", "Haoyu Chen", "Hao Tang"], "abstract": "Joint-embedding predictive architecture (JEPA) world models predict future embeddings instead of pixels and plan in latent space. Two challenges remain: 2D images leave the metric geometry that manipulation acts on implicit and entangled with appearance, and what these models imagine stays hidden, as they are mostly judged in simulation by short-horizon latent planning. We present JEPA4R, a JEPA world model that observes single-depth-camera point clouds, predicts and plans in their latent space, and acts through a policy head on its frozen latents; we call this 4D point planning. A decoder on the frozen world model shows what it imagines as 4D point clouds, with a mean point error within 1.1 cm over 200 steps. Under the policy-learning protocols of OGBench and CortexBench, JEPA4R leads pixel JEPA models on OGBench Cube-Single, Cube-Double, Cube-Triple and Scene, and ranks first on MetaWorld and Adroit Relocate with 98.4% and 88.0%, above the runner-up, R3M, at 96.0% and 65.3%. Trained only in a digital twin, JEPA4R and its policy heads run zero-shot on the real arm with both a gripper and a dexterous hand.", "published": "2026-11-15", "comment": "Code: https://github.com/AIGeeksGroup/JEPA4R, Website: https://aigeeksgroup.github.io/JEPA4R", "url": "https://arxiv.org/abs/2611.19771"}, {"id": "2611.17110", "title": "SALA: Semantically Aligned Latent Actions Enable Dual-Axis Scaling of Embodied Foundation Models", "authors": ["Jiachun Jin", "Zetong Zhou", "Haonan Wang", "Zhijie Deng"], "abstract": "Embodied foundation models hinge on diverse robot interaction data, which are costly to collect. Egocentric human videos offer a complementary source of experience, and latent action models (LAMs) provide a popular means of leveraging these videos for policy supervision. Compared with world-action models (WAMs), LAMs can offer greater training efficiency and potentially lower inference costs by avoiding explicit pixel prediction during policy learning and execution. However, most existing LAMs learn latent actions solely through video reconstruction, which can cause their representations to cluster by visual appearance rather than by the underlying actions. As a result, they struggle to align human actions with their robot counterparts. To bridge the gap, we introduce SALA, which emphasizes establishing the semantic correspondence for latent actions. Without requiring paired data, we use the language descriptions of unpaired human and robot clips to estimate semantic similarities and supervise cross-embodiment correspondence. Specifically, we translate these similarities into soft neighborhood structures that guide human latent actions toward semantically related robot latents, while robot action reconstruction grounds the latent space in control. The resulting shared latent action space provides a unified supervision signal for training an embodied foundation model on both human and robot videos. Notably, latent action supervision enables scaling along two axes: (1) pre-training on increasing amounts of general human video consistently reduces robot action prediction error on downstream tasks, and (2) post-training on increasing amounts of task-specific human video substantially improves real-world robot task success rates.", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2611.17110"}, {"id": "2611.19131", "title": "Wireless Edge-Assisted Adaptive Latent Reasoning for Vision-Language-Action Models in Physical AI", "authors": ["Fatih Temiz", "Melike Erol-Kantarci"], "abstract": "Vision-language-action (VLA) models enable embodied artificial intelligence (AI) by translating visual observations and language instructions into robotic actions. Emerging use cases in physical AI are expected to drive the need for efficient inference and communication, as the computational demands of the VLA models pose challenges for real-time control with limited onboard resources. Test-time scaling through latent reasoning allows these models to refine hidden representations without generating explicit chain-of-thought (CoT) tokens, but introduces a trade-off between task success, inference latency, and energy consumption. In this paper, we address the efficient collaborative inference under a realistic communication scenario. We propose a wireless edge-assisted framework for adaptive latent reasoning (WEALR) that augments onboard computation with edge computing. A decision-making agent jointly selects the execution location and latent-reasoning convergence threshold. We formulate this joint adaptation as a constrained Markov decision process (CMDP). A Lagrangian-constrained deep reinforcement learning (CDRL) approach, namely trust region policy optimization Lagrangian (TRPO-Lag), learns to balance task performance and resource consumption under varying wireless conditions and task requirements. We evaluate the framework using LIBERO manipulation tasks, profiled VLA inference costs, and ray-traced wireless channels. Experimental results demonstrate that TRPO-Lag achieves up to 23% higher feasibility-weighted task success rate compared to benchmark CDRL methods.", "published": "2026-11-14", "comment": "6 pages, 6 figures, submitted to IEEE ICC", "url": "https://arxiv.org/abs/2611.19131"}, {"id": "2611.19183", "title": "WA-JEPA: Goal-Aware Predictive Feedback Action Refinement for a World-Action Model", "authors": ["Tao An", "Weihang Liang", "Tianqi Wang", "Chuqing Cao", "Wenming Tan", "Kai Zhang", "Haibo Lei", "Tao Xie", "Lijun Zhao", "Ruifeng Li"], "abstract": "JEPA-based world models predict action consequences in latent space, but representative planning approaches rely on candidate-action search, requiring repeated evaluation of action sequences and incurring substantial online computational cost. Direct action generation avoids this search, yet how to leverage latent predictions to guide action generation given task goals remains a key challenge in translating learned physical dynamics into effective decisions. We introduce WA-JEPA, a world-action model that couples action generation, action-conditioned latent prediction, and goal-aware feedback. The model first generates an action proposal and predicts the resulting future scenes and proprioceptive states, then refines the proposal through two complementary feedback paths, using the task goal as a reference. Goal-discrepancy residual feedback (GDRF) uses differences between the latent representations of predicted scenes and the task goal to guide chunk-wise action refinement. Future-scene context feedback (FSCF) preserves fine-grained predicted scene representations to guide subsequent action refinement. Jointly learned from offline demonstrations, this process iteratively updates the same plan before execution, making future predictions directly participate in action generation without candidate-action search. We evaluate short-horizon goal reaching, long-horizon tasks, and full-task execution. The results show that goal-aware predictive feedback supports competitive task performance while maintaining a compact model and low online computational cost. Code is available at https://github.com/Dovisya/WA-JEPA.", "published": "2026-11-14", "comment": "16 pages, 5 figures, including supplementary material. Code available at https://github.com/Dovisya/WA-JEPA", "url": "https://arxiv.org/abs/2611.19183"}, {"id": "2608.13438", "title": "ContactGuard: Pre-Contact Execution Monitoring with Action-Conditioned Latent World Models", "authors": ["Gehan Zheng", "Matthew Johnson-Roberson", "Weiming Zhi"], "abstract": "Contact-rich manipulation failures are often detected only after the robot has committed to contact. This is especially limiting in wrist-camera setups: close gripper--object views help observe contact, but a poor approach may already push, miss, slip, or disturb the object before conventional detectors react. We introduce ContactGuard, a pre-contact execution monitor for chunked visuomotor policies. Given the policy's planned action chunk, ContactGuard predicts its short-horizon consequence in latent visual space and aborts if the predicted future latent indicates likely failure. Its latent world model is trained from unlabelled robot trajectories to predict compact multi-view visual embeddings under planned actions, avoiding pixel-level video prediction. A lightweight failure probe is then trained from a small labelled set of pre-contact clips. At deployment, ContactGuard anchors prediction before an imminent contact event, rolls the model forward under the policy's own actions, and verifies the predicted post-contact latent. Across real-world contact-rich manipulation tasks, ContactGuard consistently benefits from action-conditioned latent prediction over current-state and direct-prediction alternatives. Counterfactual action perturbations further show that its failure score responds to the specific action being proposed. We deploy the same frozen monitor online with the visuomotor policy, where it provides a pre-contact abort signal without modifying the underlying policy.", "published": "2026-11-14", "comment": "14 pages, 4 figures, 7 tables", "url": "https://arxiv.org/abs/2608.13438"}, {"id": "2611.19822", "title": "The Flip Test: Video World Models Fail to Learn the World State", "authors": ["Mi Luo", "Lijun Yu", "Adams Wei Yu", "Ang Cao", "Baochen Sun", "Ming-Hsuan Yang", "Nan Hua", "Yuan Hao", "Alex Dimakis", "Ya Xu", "Ed H. Chi", "Xuezhi Wang", "Yinxiao Liu"], "abstract": "Video world models promise to predict the future of a scene from its present. Do current models keep this promise? We probe this question counterfactually. When a small change to the present flips the future, such as a box resting a few millimeters before or past a table edge, a model that tracks the state of the world must flip its prediction too. We build FlipTest, a three-level hierarchy of increasingly strict tests over 1,680 initial frames from 10 simulated and 15 real-world tasks. At the base, visual minimal pairs, two nearly identical frames whose true futures differ, test whether predictions change across the boundary; matched controls go further and test whether they change only where the future does; and dense sweeps, the strictest level, locate exactly where they change. All 11 video world models we evaluate fall short. The best averages 18.3% pair accuracy over real and simulated scenes, below the 25% of random guessing. Models flip as often on steps that leave the future unchanged as on steps that change it, and their response stays flat across the sweeps. On the same frames, a vision-language model is selective and traces a near S-shaped curve near the boundary, and a coding agent that measures the image comes close to the true boundary. This implies that the deciding information is in the frame, and video models just miss it. We therefore urge the community to rethink world modeling as pure video prediction. Next-frame prediction must do more than draw plausible pixels; it must also identify the causal states that control future dynamics.", "published": "2026-11-15", "comment": "Project Page: https://flip-test.github.io/", "url": "https://arxiv.org/abs/2611.19822"}, {"id": "2611.20107", "title": "SAFER: Navigating the Exploration-Exploitation Dilemma in World-Model-Based Planning for Autonomous Driving", "authors": ["Yansong Qu", "Zilin Huang", "Zihao Sheng", "Sikai Chen", "Samuel Labi"], "abstract": "An autonomous vehicle must foresee the consequences of its actions, especially in the rare, time-critical situations where crashes happen. A world model offers this foresight, but only within the coverage of its training data, which poses an exploration-exploitation dilemma. Within this coverage a planner can hardly improve on the data, and beyond it the model's errors mislead it. Logs of competent driving rarely contain the failures that would widen the coverage, and agents that learn from interaction gain them only by failing themselves, without being shown what to do instead. We propose SAFER, a framework that learns offline from failures that others make, judged by an expert, and keeps learning online from its own driving. Offline, partially trained agents and scripted, recoverable perturbations Stage failures in simulation, and an expert Annotates every visited state with its action and value, so that much of what the planner explores is covered before it drives. In planning, a chunked latent world model Foresees the consequences fast enough for real-time use, and a risk-aware sampling-based planner Evaluates candidate maneuvers by their return minus a bounded collision penalty. Online, a loop continuously Refines the model wherever this driving leaves the coverage of the offline data. In closed-loop evaluation against the compared methods, SAFER reaches the highest route completion and reward per step on the CARLA Leaderboard routes, 0.95 and 0.77 from a privileged bird's-eye view, and the highest episode reward in MetaDrive, 53.4 in regular and 49.0 in safety-critical traffic. Project page: https://ys-qu.github.io/safer-website.", "published": "2026-11-15", "comment": null, "url": "https://arxiv.org/abs/2611.20107"}, {"id": "2611.20307", "title": "PoCoAttn: Position-Content Collaborative Sparse Attention for Fast and High-Fidelity Video Generation", "authors": ["Jianwen Wu", "Meiling Wang", "Junkang Zhou", "Yipeng Shen", "Haoran You"], "abstract": "Video diffusion transformers rely on 3D full attention over tens of thousands of spatiotemporal tokens, and its quadratic cost dominates inference latency. Sparse attention reduces this cost, but existing methods face a dilemma: static methods apply predefined masks and cannot capture input-dependent attention, whereas dynamic methods reconstruct the sparse mask repeatedly, paying online to rediscover positional structure that is largely stable across inputs. To this end, we propose PoCoAttn, a training-free sparse attention framework that separates input-stable from input-dependent attention and resolves the former offline and the latter online. PoCoAttn features: (1) A relative-offset analysis of 3D query-key pairs, which shows that video attention decomposes into an input-stable positional prior that carries most of the attention mass and a small content-dependent residual. (2) A position-content collaborative sparse attention mechanism, which retrieves positional keys from offline-calibrated tables, selects content keys online with a head-adaptive ratio between the two sources, and compensates for the discarded keys to approximate full attention. (3) A step-adaptive budget allocation algorithm, which models how early-step sparse attention errors are amplified along the denoising trajectory and derives the optimal sparsity budget per step. Extensive experiments across four video diffusion models and three tasks show that PoCoAttn consistently achieves a better speed-fidelity Pareto frontier than state-of-the-art (SOTA) methods, improving PSNR by 1.9 to 5.0 dB over baselines and delivering up to 4.1$\\times$ attention and 2.0$\\times$ denoising speedups over dense FlashAttention-3 attention.", "published": "2026-11-15", "comment": "21 pages, 15 figures, 13 tables. Project page: https://ecoai-group.github.io/pocoattn", "url": "https://arxiv.org/abs/2611.20307"}, {"id": "2607.05133", "title": "UNIVERSE: Unified Video Action Models for Autonomous Driving with Flexible Mask-Modulated Modality Generation", "authors": ["Mengmeng Liu", "Diankun Zhang", "Jiuming Liu", "Jianfeng Cui", "Hongwei Xie", "Guang Chen", "Hangjun Ye", "Francesco Nex", "Hao Cheng", "Michael Ying Yang"], "abstract": "World Action Models (WAMs) can improve action generalization in autonomous driving by learning scene dynamics through dense future-video supervision. However, deploying such models often requires costly future-video generation, while architectures that bypass video rollout typically separate video and action parameters or alter their learned dependencies at inference. We introduce UNIVERSE, a unified video-action model built on a single mask-modulated Diffusion Transformer (DiT) that combines shared-parameter learning with modality-independent inference. Its Modality-Decoupling Visibility Mask allows future video and trajectory tokens to attend to a common historical context while blocking mutual attention between the two future modalities. As a result, future-video supervision directly updates the parameters used for trajectory denoising, yet video tokens can be omitted at test time without changing the trajectory branch's training-time attention dependencies. The same model supports trajectory-only, video-only, and joint video-action generation. Trajectory-only inference achieves a 4.3x speedup over coupled video-action rollout with comparable planning accuracy. UNIVERSE achieves 91.0 PDMS on NAVSIM, compared with 89.6 for a Two-DiT variant, and demonstrates strong zero-shot transfer to nuScenes and Bench2Drive without target-domain fine-tuning. Controlled ablations further support the complementary benefits of shared parameters, dense video co-training, and modality-decoupled visibility.", "published": "2026-11-16", "comment": "Accepted by NeurIPS 2026. Code: https://github.com/xiaomi-mlab/UNIVERSE", "url": "https://arxiv.org/abs/2607.05133"}, {"id": "2611.20510", "title": "WTR-Drive: World-Task Decomposition with Structured Risk Supervision for End-to-End Driving", "authors": ["Haoyu Xing", "Shaobing Ding", "Guanglei Zhao", "Guanhua Zhao", "Nawu Peng", "Mingyang Hou"], "abstract": "Proposal-conditioned scene predictions can lack a common object-level reference across candidate trajectories. Aggregate planning scores also leave the objects and times associated with violations implicit. We present WTR-Drive (World-Task-Risk Driving), a Drive-JEPA-based planner that separates shared scene estimation from proposal-conditioned reasoning. A proposal-independent World Memory estimates object states, map structure, and future motion by re-reading the original visual features at each refinement round. Proposal feedback updates a residual Task branch without writing back to World Memory. This branch guides refinement through candidate-specific retrieval and gated visual feedback. A final Task readout supplies candidate-conditioned features for scoring. We derive structured risk targets from existing candidate-scoring rollouts without additional simulator calls. For at-fault collision and time-to-collision violations, the targets encode event existence, association with shared object slots, and the first violation time bin. On the NAVSIM navtest split, WTR-Drive achieves 94.66 PDMS on v1 and 88.24 EPDMS on v2 (expert-frame sequential evaluation). These scores are 0.96 and 0.44 points above the published Drive-JEPA values, respectively. Candidate-level analysis shows that higher best-candidate scores can coexist with lower selected-trajectory scores, revealing a gap between candidate quality and selection effectiveness.", "published": "2026-11-16", "comment": "8 pages, 5 figures, 3 tables. Submitted to IEEE Intelligent Vehicles Symposium (IV) 2027", "url": "https://arxiv.org/abs/2611.20510"}, {"id": "2610.11161", "title": "VGGT-VLA-World: Intent-Conditioned 3D World Evolution for Autonomous Driving", "authors": ["Zhaoyang Liu", "Zhigui Lin", "Kun Jiang", "Tianhui Li", "Changye Liu", "Ziying Song", "Diange Yang"], "abstract": "VGGT provides a strong foundation for geometry-centric world models by recovering unified 3D scene geometry from visual observations. Although recent extensions enable temporal 3D prediction, their future evolution remains weakly conditioned on driving intentions and actions, limiting their ability to model alternative action-dependent futures. We propose \\textbf{VGGTWorld-VLA}, an intention-conditioned extension of VGGT-World for controllable 3D world evolution in autonomous driving. First, we introduce an action--semantic conditioning mechanism that injects complementary driving semantics and ego-motion representations into the future-token stream, enabling different future geometry predictions for the same observed scene under alternative ego actions. Second, we develop a geometry--language--action bridge that adapts historical geometry, VLA semantic features, and maneuver and trajectory representations for joint conditioning of future geometry prediction. We evaluate future geometry prediction on NAVSIM, with ablation studies examining the contributions of semantic and action conditioning. Compared with baseline, our method reduces future-depth RMSE by 13.7\\% and improves $δ_1$ by 4.11 percentage points on NAVSIM motion subset. Controlled action-input interventions further show that the model uses the supplied action information. These results support semantic and action conditioning for controllable VGGT-based world prediction in autonomous driving.", "published": "2026-11-16", "comment": "12 pages, 9 figures", "url": "https://arxiv.org/abs/2610.11161"}, {"id": "2611.17060", "title": "Ropedia Xperience 2: A Gold Standard for Scaling Physical AI Environments and Behaviors", "authors": ["Hao Li", "Fangzhou Hong", "Zhaoxi Chen", "Hui En Pang", "Kairui Hu", "Mingze Sun", "Runmao Yao", "Xinhao Ji", "Xiyuan Zheng", "Xuanli Chen", "Yalun Dai", "Yap Kim Hui", "Dingwen Zhang", "Yuanyuan Gao", "Ziang Cao", "Cheng Huang Yean", "Jackson Peng", "Yichen Zhao", "Rui Duan", "Yaobo Liu", "Zetong Wang", "Ziwei Liu"], "abstract": "Large foundation models such as GPT-6 Astra and Claude Fable 5.1 have recently been shown to control robots directly from visual observations. They nevertheless remain brittle on long-horizon, contact-rich tasks in real-world environments. Further progress depends on two complementary resources: demonstrations of human behavior that supervise how tasks are performed, and interactive environments in which policies can be rolled out, evaluated, and improved in closed loop. Language models have advanced along well-characterized scaling laws; the corresponding question for physical AI is how capability scales with environments and behaviors, which first requires identifying which data to scale and how to produce and reuse such data continuously. To address this question, we introduce Ropedia Xperience 2, comprising 1,589 released metric-scale 3D scans and a collection of 4,230 egocentric recordings of 74 tasks (131 hours). We further show that each capture can be repurposed for robot learning: scenes are converted into physically interactive simulation environments, human motion is retargeted to whole-body robot trajectories, and additional robot behaviors are obtained through virtual teleoperation and automated long-horizon trajectory generation. We propose this joint capture of environments and behaviors as a gold standard for physical AI data collection, laying a data foundation for establishing scaling laws over environments and behaviors.", "published": "2026-11-16", "comment": "https://ropedia.com/xperience/2-research", "url": "https://arxiv.org/abs/2611.17060"}]}}};
